REPLACE_NONE = "None"

def task_func(json_str):
    data = json.loads(json_str)

    def process(obj):
        if isinstance(obj, dict):
            return {k: process(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [process(item) for item in obj]
        elif obj is None:
            return REPLACE_NONE
        elif isinstance(obj, str):
            email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
            if re.match(email_pattern, obj):
                return REPLACE_NONE
            return obj
        else:
            return obj

    processed = process(data)

    def flatten(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(flatten(v))
        elif isinstance(obj, list):
            for item in obj:
                values.extend(flatten(item))
        else:
            values.append(obj)
        return values

    all_values = flatten(processed)
    value_counts = Counter(all_values)

    return {"data": processed, "value_counts": value_counts}

